-- DEV16: venue-facing planning notes. V60/V61/V62 and the original payload are unchanged.
-- Match one original room by identity, including retained legacy UUIDs. Never overwrite
-- staff-edited notes, renamed/readdressed rooms, or ambiguous duplicate identities.
WITH replacements(seed_id, venue_name, venue_address, previous_note, staff_note) AS (
  VALUES
    ('46be4c26-2ba7-57c8-80cb-f52f608e43d2', 'SMU Yong Pung How School of Law – Seminar Room 3-09, Level 3', 'SMU Yong Pung How School of Law – Seminar Room 3-09, Level 3, 55 Armenian Street, Singapore 179943', 'Level 3, Seminar Room 3-09. Teaching/seminar space; campus security access may be required.', 'Level 3, Seminar Room 3-09. Teaching and seminar space. Confirm any campus security access requirements before the event.'),
    ('bc3f56c5-6a2a-5283-a977-fbf102f0f71c', 'SMU Yong Pung How School of Law – SMU Hall 3, Basement 1', 'SMU Yong Pung How School of Law – SMU Hall 3, Basement 1, 55 Armenian Street, Singapore 179943', 'Basement 1, SMU Hall 3. Separate booking from the Level 3 seminar rooms.', 'Basement 1, SMU Hall 3. This hall is booked separately from the Level 3 seminar rooms.'),
    ('036adc01-b7d8-5fc9-9d97-c5299a933d2d', 'NUS University Cultural Centre – Ho Bee Auditorium', 'NUS University Cultural Centre – Ho Bee Auditorium, 50 Kent Ridge Crescent, Singapore 119279', 'Fixed auditorium seating; published default 1,607 seats includes wheelchair spaces. Larger configuration requires separate arrangements.', 'Fixed auditorium seating. The published standard configuration seats 1,607 people, including wheelchair spaces. Larger configurations require separate arrangements with the venue operator.'),
    ('62479f09-2111-5391-8a8f-fc510e166fbc', 'NUS University Cultural Centre – Theatre', 'NUS University Cultural Centre – Theatre, 50 Kent Ridge Crescent, Singapore 119279', '425 seats including six wheelchair spaces; additional flat-floor configuration needs approval.', 'The theatre seats 425 people, including six wheelchair spaces. A flat-floor configuration requires approval from the venue operator.'),
    ('6dd9f923-7f22-5ac7-87ac-6f2f7e935972', 'NUS University Cultural Centre – Function Room 1, Level 1', 'NUS University Cultural Centre – Function Room 1, Level 1, 50 Kent Ridge Crescent, Singapore 119279', 'Level 1 ancillary function room. Published theatre-style maximum is 50; room is unfurnished by default.', 'Level 1 function room, supplied unfurnished. The published theatre-style maximum is 50 people. Arrange the required furniture and room setup before the event.'),
    ('d077d8be-4446-5b3a-9990-7c01ab97d8d8', 'NTU – Nanyang Auditorium Theatre', 'NTU – Nanyang Auditorium Theatre, 50 Nanyang Avenue, Singapore 639798', 'Nanyang Auditorium main theatre. Published 1,526 seats, including two designated wheelchair spaces.', 'Main theatre in Nanyang Auditorium. Published seating capacity is 1,526 people, including two designated wheelchair spaces.'),
    ('31cc055b-3c23-5957-a8b8-035055d3a6d1', 'Lifelong Learning Institute – Training Room 1-1, Level 1', 'Lifelong Learning Institute – Training Room 1-1, Level 1, 11 Eunos Road 8, Singapore 408601', 'Level 1, Training Room 1-1. Test capacity set within published 30–50-person range.', 'Level 1, Training Room 1-1. Published capacity guidance is 30–50 people. Confirm the capacity for the requested seating layout before approval.'),
    ('f61189c6-500a-5ed8-adb4-79c8781421f4', 'Lifelong Learning Institute – Event Hall 1-1, Level 1', 'Lifelong Learning Institute – Event Hall 1-1, Level 1, 11 Eunos Road 8, Singapore 408601', 'Level 1; adjacent to Hall 1-2. Published approximate capacity: 90–100 classroom, 150–180 theatre. Seed 90 for both layouts; combined-hall bookings need separate conflict handling.', 'Level 1, next to Hall 1-2. Published guidance is approximately 90–100 people in classroom seating or 150–180 in theatre seating. The recorded planning limit is 90 people. Confirm the layout and any combined-hall arrangements with the venue operator before approval.'),
    ('06eab6fa-a842-5c76-81e8-dff35e7936c2', 'Lifelong Learning Institute – Lecture Theatre', 'Lifelong Learning Institute – Lecture Theatre, 11 Eunos Road 8, Singapore 408601', 'Dedicated lecture theatre. Published capacity 267.', 'Dedicated lecture theatre with a published seating capacity of 267 people.'),
    ('c94f126a-199c-5613-9007-00afefd8ff74', 'Singapore Chinese Cultural Centre – Auditorium, Levels 9–10', 'Singapore Chinese Cultural Centre – Auditorium, Levels 9–10, 1 Straits Boulevard, Singapore 018906', 'Auditorium on Levels 9–10; published capacity 533. Performing arts venue.', 'Performing arts auditorium on Levels 9–10. Published seating capacity is 533 people.'),
    ('08ef8aae-a75c-5629-9e92-04973d87cda2', 'Singapore Chinese Cultural Centre – Multi-Purpose Hall, Level 7', 'Singapore Chinese Cultural Centre – Multi-Purpose Hall, Level 7, 1 Straits Boulevard, Singapore 018906', 'Level 7. Published maximum: 300 classroom, 550 theatre, 550 banquet; 300 chosen because the app uses one capacity across layouts.', 'Level 7 multi-purpose hall. Published layout guidance is 300 people in classroom seating, or 550 in theatre or banquet seating. The recorded planning limit is 300 people. Confirm the capacity for the requested layout before approval.'),
    ('a58c2a81-72b4-5859-8c20-860d39ba1def', 'Singapore Chinese Cultural Centre – Creative Box, Level 6', 'Singapore Chinese Cultural Centre – Creative Box, Level 6, 1 Straits Boulevard, Singapore 018906', 'Level 6 flexible event space; published 120-person maximum. Seed conservatively at 100.', 'Flexible event space on Level 6. The published maximum is 120 people; the recorded planning limit is 100. Confirm the final setup and capacity with the venue operator.'),
    ('67084cb8-b2ee-5908-9b99-010d43119e00', 'Esplanade – Concert Hall', 'Esplanade – Concert Hall, 1 Esplanade Drive, Singapore 038981', 'Published main-house seating 1,628, excluding 197 additional gallery seats. Production access may require extra coordination.', 'Published main-house seating is 1,628 people, excluding 197 additional gallery seats. Coordinate production access and any gallery seating requirements with the venue operator.'),
    ('69ed6970-c0b8-5559-801d-2cf4b3e5b0fe', 'Esplanade – Recital Studio, Level 2', 'Esplanade – Recital Studio, Level 2, 1 Esplanade Drive, Singapore 038981', 'Level 2, flexible studio with 245 seats on retractable bleachers; fixed theatre capacity used for this test record.', 'Flexible studio on Level 2, with 245 seats on retractable bleachers. Confirm the setup and capacity with the venue operator if a different seating arrangement is required.'),
    ('1537e784-29ce-55b1-911e-9f06464fca41', 'The Star Performing Arts Centre – The Star Theatre', 'The Star Performing Arts Centre – The Star Theatre, 1 Vista Exchange Green, Singapore 138617', 'Theatre occupies Levels 5–10. Published full-house capacity 5,000; tier-limited booking is not modelled here.', 'The theatre occupies Levels 5–10, with a published full-house capacity of 5,000 people. This listing covers the full theatre. Confirm any plans to use selected seating tiers with the venue operator.'),
    ('a3ce78ee-ceaa-54e2-8bec-94d0f81c04b6', 'Singapore EXPO – Exhibition Hall 1', 'Singapore EXPO – Exhibition Hall 1, 1 Expo Drive, Singapore 486150', 'Hall 1 is individually identifiable. Venue operator quotes up to 9,000 pax per hall; 6,000 is a fictional test cap, not an official configuration-specific limit.', 'Exhibition Hall 1. The venue operator quotes up to 9,000 people per hall. The recorded 6,000-person planning limit is illustrative and is not an operator-approved capacity for a specific layout. Confirm the layout and capacity with the venue operator before approving a booking.'),
    ('683a8a3b-40bc-54d5-9aaf-f626ce15b145', 'Sands Expo & Convention Centre – Sands Grand Ballroom', 'Sands Expo & Convention Centre – Sands Grand Ballroom, 10 Bayfront Avenue, Singapore 018956', 'Sands Grand Ballroom can accommodate up to 8,000 guests in some configurations. Seed cap 5,000 is illustrative for selected layouts.', 'Some ballroom configurations accommodate up to 8,000 guests. The recorded 5,000-person planning limit is illustrative. Confirm the approved capacity for the requested layout with the venue operator.'),
    ('d14ca2e7-27f5-5910-9962-7a8cbe53da66', 'Suntec Singapore Convention & Exhibition Centre – Hall 401, Level 4', 'Suntec Singapore Convention & Exhibition Centre – Hall 401, Level 4, 1 Raffles Boulevard, Singapore 039593', 'Level 4, Hall 401 is used for events. Test capacity 1,200 is not an operator-published figure. Do not assume combined hall layouts are independently reservable.', 'Event hall on Level 4. The recorded 1,200-person planning limit has not been confirmed by the venue operator. Confirm the capacity for the requested layout. Combined halls require separate confirmation of availability and booking arrangements.'),
    ('90429ced-61d8-5926-aeed-5e7a7807be3c', 'Victoria Theatre & Concert Hall – Victoria Concert Hall', 'Victoria Theatre & Concert Hall – Victoria Concert Hall, 9 Empress Place, Singapore 179556', 'Concert hall inside the Victoria Theatre & Concert Hall complex. Published seating 673.', 'Concert hall within the Victoria Theatre & Concert Hall complex, with published seating for 673 people.'),
    ('b590ea20-590f-5fc8-a1ca-22d76537dd9d', 'The Arts House at the Old Parliament – Chamber', 'The Arts House at the Old Parliament – Chamber, 1 Old Parliament Lane, Singapore 179429', 'The former parliamentary Chamber has 187 seats per Arts House Group venue sales kit. Accessibility left blank intentionally (unrecorded, not ''No accessibility provisions'').', 'Former parliamentary Chamber, with published seating for 187 people. Accessibility provisions have not been recorded; confirm them with the venue operator when reviewing accessibility requirements.')
), candidates AS (
  SELECT v.venue_id, r.previous_note, r.staff_note,
         count(*) OVER (PARTITION BY r.seed_id) AS identity_matches
  FROM venues v JOIN replacements r
    ON lower(regexp_replace(btrim(v.venue_address), '\s+', ' ', 'g')) =
       lower(regexp_replace(btrim(r.venue_address), '\s+', ' ', 'g'))
   AND (lower(regexp_replace(btrim(v.venue_name), '\s+', ' ', 'g')) =
        lower(regexp_replace(btrim(r.venue_name), '\s+', ' ', 'g'))
        OR lower(regexp_replace(btrim(v.venue_name), '\s+', ' ', 'g')) =
           lower(regexp_replace(btrim(r.venue_address), '\s+', ' ', 'g')))
)
UPDATE venues v SET additional_information = c.staff_note
FROM candidates c
WHERE v.venue_id = c.venue_id AND c.identity_matches = 1
  AND v.additional_information IS NOT DISTINCT FROM c.previous_note;
